#!/usr/bin/env node
import path from "node:path";
import { pathToFileURL } from "node:url";
import {
  contentStatusByTopicStatus,
  buildTopicMetadata,
} from "./build-topic-metadata.mjs";
import {
  readCurriculumCorpus,
  repositoryRoot,
  serializeJson,
  writeGeneratedFile,
} from "./curriculum-corpus.mjs";

const auditRoot = path.join(repositoryRoot, "_audit");
const jsonFile = path.join(auditRoot, "coverage-report.json");
const markdownFile = path.join(auditRoot, "coverage-report.md");

const preamble = [
  "# Content coverage report",
  "",
  "Generated by `scripts/build-coverage-report.mjs` from `content-v2/` and the metadata sidecar in `content-v2/indexes/`. Do not edit by hand.",
  "",
  "## What these numbers mean",
  "",
  "Coverage here counts **what exists**, not what is correct. A topic is counted as having college notes, an ELI-10 explanation or references when its bundle says that section is present. A course scoring well has material in most sections and questions attached to it.",
  "",
  "## What these numbers do not mean",
  "",
  "- They are not a quality or accuracy score. Nothing is counted as good, current or clinically safe.",
  "- **No content in this repository has a documented credentialed clinical review.** `Published` means the material is grounded in cited source text and complete enough to study, nothing more.",
  "- `Citation review` counts questions the importers flagged for citation checking. It is a workflow flag on the question, not a judgement about the topic it maps to.",
  "- Question counts include every question in a course's bank: exact-mapped, subject-wide overlay and broad-source-topic placements alike. The same question can be counted once per course it is placed in.",
  "- `Held` topics are flagged for medical review and are deliberately withheld from study. `Draft` topics are incomplete. Neither is published.",
  "",
];

const columns = [
  ["Course", (row) => row.title],
  ["Topics", (row) => row.topicCount],
  ["College notes", (row) => row.collegeNoteCount],
  ["ELI-10", (row) => row.eli10Count],
  ["References", (row) => row.referencesCount],
  ["Questions", (row) => row.questionCount],
  ["Citation review", (row) => row.citationReviewQuestionCount],
  ["Published", (row) => row.publishedCount],
  ["Held", (row) => row.heldCount],
  ["Draft", (row) => row.draftCount],
];

export const buildCoverageReport = () => {
  const corpus = readCurriculumCorpus();
  const metadata = buildTopicMetadata();
  const courses = corpus.subjects.map((subject) => {
    const statuses = subject.topics.map((topic) => metadata.topics[topic.bundle.id]?.contentStatus ?? contentStatusByTopicStatus[topic.bundle.status]);
    const available = (key) => subject.topics.filter((topic) => topic.bundle.availability?.[key] === true).length;
    return {
      slug: subject.summary.slug,
      title: subject.summary.title,
      category: subject.summary.category,
      status: subject.summary.status,
      topicCount: subject.topics.length,
      collegeNoteCount: available("collegeNotes"),
      eli10Count: available("eli10"),
      referencesCount: available("references"),
      questionCount: subject.questions.length,
      citationReviewQuestionCount: subject.questions.filter((question) => question.citationReviewRequired === true).length,
      publishedCount: statuses.filter((status) => status === "source-grounded").length,
      heldCount: statuses.filter((status) => status === "needs-medical-review").length,
      draftCount: statuses.filter((status) => status === "draft").length,
    };
  });
  const sum = (key) => courses.reduce((total, course) => total + course[key], 0);
  return {
    schemaVersion: "1.0.0",
    generatedOn: corpus.catalog.generatedOn,
    generatedBy: "scripts/build-coverage-report.mjs",
    coverageMeans: "Counts of material that exists. Not a quality score, and not evidence of clinical review.",
    totals: {
      courses: courses.length,
      topics: sum("topicCount"),
      collegeNotes: sum("collegeNoteCount"),
      eli10: sum("eli10Count"),
      references: sum("referencesCount"),
      questions: sum("questionCount"),
      citationReviewQuestions: sum("citationReviewQuestionCount"),
      published: sum("publishedCount"),
      held: sum("heldCount"),
      draft: sum("draftCount"),
    },
    courses,
  };
};

const renderRow = (cells) => `| ${cells.join(" | ")} |`;

export const renderCoverageMarkdown = (report) => {
  const lines = [...preamble];
  lines.push(`Generated on ${report.generatedOn} from ${report.totals.courses} courses in catalog order.`, "");
  lines.push(renderRow(columns.map(([label]) => label)));
  lines.push(renderRow(columns.map(([, ], index) => (index === 0 ? "---" : "---:"))));
  for (const course of report.courses) lines.push(renderRow(columns.map(([, read]) => String(read(course)))));
  lines.push(renderRow([
    "**Total**",
    ...[report.totals.topics, report.totals.collegeNotes, report.totals.eli10, report.totals.references,
      report.totals.questions, report.totals.citationReviewQuestions, report.totals.published,
      report.totals.held, report.totals.draft].map((value) => `**${value}**`),
  ]));
  lines.push("");
  lines.push(`Across the library: ${report.totals.published} topics are published, ${report.totals.held} are held for medical review and ${report.totals.draft} are drafts. None of the published topics has a documented credentialed clinical review.`);
  lines.push("");
  return lines.join("\n");
};

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const report = buildCoverageReport();
  writeGeneratedFile(jsonFile, serializeJson(report));
  writeGeneratedFile(markdownFile, renderCoverageMarkdown(report));
  console.log(`Wrote ${path.relative(repositoryRoot, jsonFile)} and ${path.relative(repositoryRoot, markdownFile)}`);
  console.log(`${report.totals.courses} courses; ${report.totals.topics} topics; ${report.totals.published} published; ${report.totals.held} held; ${report.totals.draft} draft.`);
}
